module HazardDetectionUnit(
    input clk,
    input Branch_ID, rs1use_ID, rs2use_ID,
    input[1:0] hazard_optype_ID,
    input[4:0] rd_EXE, rd_MEM, rs1_ID, rs2_ID, rs2_EXE,
    output PC_EN_IF, reg_FD_EN, reg_FD_stall, reg_FD_flush,
        reg_DE_EN, reg_DE_flush, reg_EM_EN, reg_EM_flush, reg_MW_EN,
    output forward_ctrl_ls,
    output[1:0] forward_ctrl_A, forward_ctrl_B
);
    reg[1:0] hazard_optype_EXE, hazard_optype_MEM;

    initial begin
        hazard_optype_EXE = 2'b00;
        hazard_optype_MEM = 2'b00;
    end

    always @(posedge clk) begin
        hazard_optype_MEM <= hazard_optype_EXE & {2{~reg_EM_flush}};
        hazard_optype_EXE <= hazard_optype_ID & {2{~reg_DE_flush}};
    end

    wire rs1_conflict_EXE = rs1use_ID && (rs1_ID != 0) && (rs1_ID == rd_EXE) &&
                            (hazard_optype_EXE != 2'b00);
    wire rs2_conflict_EXE = rs2use_ID && (rs2_ID != 0) && (rs2_ID == rd_EXE) &&
                            (hazard_optype_EXE != 2'b00);
    wire data_stall = rs1_conflict_EXE | rs2_conflict_EXE;

    wire rs1_forward_MEM = rs1use_ID && (rs1_ID != 0) && (rs1_ID == rd_MEM) &&
                           (hazard_optype_MEM != 2'b00);
    wire rs2_forward_MEM = rs2use_ID && (rs2_ID != 0) && (rs2_ID == rd_MEM) &&
                           (hazard_optype_MEM != 2'b00);

    assign PC_EN_IF     = ~data_stall;
    assign reg_FD_EN    = 1'b1;
    assign reg_FD_stall = data_stall;
    assign reg_FD_flush = Branch_ID & ~data_stall;
    assign reg_DE_EN    = 1'b1;
    assign reg_DE_flush = data_stall;
    assign reg_EM_EN    = 1'b1;
    assign reg_EM_flush = 1'b0;
    assign reg_MW_EN    = 1'b1;
    assign forward_ctrl_ls = (rs2_EXE != 0) && (rs2_EXE == rd_MEM) &&
                             (hazard_optype_MEM != 2'b00);
    assign forward_ctrl_A  = rs1_forward_MEM ? 2'b01 : 2'b00;
    assign forward_ctrl_B  = rs2_forward_MEM ? 2'b01 : 2'b00;

endmodule

