/workspace/agent_tests/lab1_smoke_tb.v.content:
`timescale 1ns / 1ps

module lab1_smoke_tb;
    reg clk = 1'b0;
    reg rst = 1'b1;
    reg debug_en = 1'b0;
    reg debug_step = 1'b0;
    reg [6:0] debug_addr = 7'b0;

    wire [31:0] debug_data;
    wire [31:0] pc;
    wire [31:0] inst;
    wire [31:0] mem_addr;
    wire [31:0] mem_data;

    reg [5:0] seen = 6'b0;

    RV32core dut(
        .debug_en(debug_en),
        .debug_step(debug_step),
        .debug_addr(debug_addr),
        .debug_data(debug_data),
        .clk(clk),
        .rst(rst),
        .interrupter(1'b0),
        .pc(pc),
        .inst(inst),
        .mem_addr(mem_addr),
        .mem_data(mem_data)
    );

    always #1 clk = ~clk;

    initial begin
        #2 rst = 1'b0;
    end

    always @(negedge clk) begin
        if (!rst && dut.RegWrite_WB) begin
            case (dut.PC_WB)
                32'h00000004: begin
                    if (dut.rd_WB !== 5'd2 || dut.wt_data_WB !== 32'h00000008)
                        $fatal(1, "lab1 checkpoint 0 failed: rd=%0d data=%h", dut.rd_WB, dut.wt_data_WB);
                    seen[0] <= 1'b1;
                end
                32'h0000000c: begin
                    if (dut.rd_WB !== 5'd1 || dut.wt_data_WB !== 32'h00000018)
                        $fatal(1, "lab1 checkpoint 1 failed: rd=%0d data=%h", dut.rd_WB, dut.wt_data_WB);
                    seen[1] <= 1'b1;
                end
                32'h00000040: begin
                    if (dut.rd_WB !== 5'd1 || dut.wt_data_WB !== 32'hffffff00)
                        $fatal(1, "lab1 checkpoint 2 failed: rd=%0d data=%h", dut.rd_WB, dut.wt_data_WB);
                    seen[2] <= 1'b1;
                end
                32'h000000e8: begin
                    if (dut.rd_WB !== 5'd1 || dut.wt_data_WB !== 32'h00004000)
                        $fatal(1, "lab1 checkpoint 3 failed: rd=%0d data=%h", dut.rd_WB, dut.wt_data_WB);
                    seen[3] <= 1'b1;
                end
                32'h00000100: begin
                    if (dut.rd_WB !== 5'd1 || dut.wt_data_WB !== 32'hff000f0f)
                        $fatal(1, "lab1 checkpoint 4 failed: rd=%0d data=%h", dut.rd_WB, dut.wt_data_WB);
                    seen[4] <= 1'b1;
                end
                32'h00000124: begin
                    if (dut.rd_WB !== 5'd1 || dut.wt_data_WB !== 32'hffff0124)
                        $fatal(1, "lab1 checkpoint 5 failed: rd=%0d data=%h", dut.rd_WB, dut.wt_data_WB);
                    seen[5] <= 1'b1;
                end
            endcase

            if (&seen)
                $finish;
        end
    end

    initial begin
        repeat (400) @(negedge clk);
        $fatal(1, "lab1 timeout: seen=%b last_pc=%h", seen, dut.PC_WB);
    end
endmodule

